From 4646a86cd255ac9f372bbf5f5c60174014745d47 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:47:51 +0100
Subject: [PATCH] applets/digital-clock: Don't zero the seconds in Copy to
 Clipboard

When the clock hid seconds, the menu set them to 0 by hand, so entries
that show seconds anyway (the long time format, also the C locale's
short one) showed and copied a wrong time. Use the current time as is.

BUG: 468771
---
 applets/digital-clock/plugin/clipboardmenu.cpp | 4 ----
 1 file changed, 4 deletions(-)

diff --git a/applets/digital-clock/plugin/clipboardmenu.cpp b/applets/digital-clock/plugin/clipboardmenu.cpp
index 8e2708252f..907d3c0559 100644
--- a/applets/digital-clock/plugin/clipboardmenu.cpp
+++ b/applets/digital-clock/plugin/clipboardmenu.cpp
@@ -55,10 +55,6 @@ void ClipboardMenu::setupMenu(QAction *action)
         if (!m_timezone.isEmpty()) {
             currentDateTime.setTimeZone(QTimeZone(m_timezone));
         }
-        if (!m_secondsIncluded) {
-            QTime timeWithoutSeconds(currentDateTime.time().hour(), currentDateTime.time().minute(), 0);
-            currentDateTime.setTime(timeWithoutSeconds);
-        }

         const QDate date = currentDateTime.date();
         const QTime time = currentDateTime.time();
-- 
